head.script:
scwin.gVar = {
    "cTabIndexTarget" : "",
    "cTabIndexInput" : "",
    "cTabIndexButton" : "",
    "cTabIndexSelectBox" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > tabIndex]<br/>Tab 키를 사용하여 컴포넌트 간 포커스를 이동할 때 컴포넌트의 순서를 설정합니다.",
    "validation" : [
        "Tab 키에 의한 포커스 이동 순서를 양수, 0, 음수로 설정할 수 있어야 합니다",
        "미설정 시 0 으로 적용되어야 합니다.",
        "양수로 설정된 컴포넌트 중 작은 숫자의 컴포넌트부터 포커스를 받아야 합니다.", 
        "0 으로 설정된 컴포넌트는 양수로 설정된 컴포넌트를 모두 순회한 후 포커스가 이동되어야 합니다.",        
        "음수로 설정된 컴포넌트는 포커스 이동에서 제외되어야 합니다.",
        "동일한 값을 설정한 경우 소스에 정의된 순서대로 포커스가 이동되어야 합니다 .",
        "renderType=component 일때 아이템 리스트가 표시된 상태이면 Tab 키로 포커스 이동을 할 수 없습니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
	let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};




scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 기존 input2 있으면 삭제
    if (typeof input2 !== 'undefined') {
        input2.remove();
    }

    // 기존 button2 있으면 삭제
    if (typeof button2 !== 'undefined') {
        button2.remove();
    }

    // 기존 selectbox2 있으면 삭제
    if (typeof selectbox2 !== 'undefined') {
        selectbox2.remove();
    }

    // 조건 설정 (target)   
    let properties = {
        tabIndex: scwin.gVar["cTabIndexTarget"],
    };

    let cList = $c.gcm.createCList(properties);      

    // 조건 설정 (input)
    let properties_input = {
        tabIndex: scwin.gVar["cTabIndexInput"],
    };

    let cList_input = $c.gcm.createCList(properties_input);    

    // 조건 설정 (button)
    let properties_button = {
        tabIndex: scwin.gVar["cTabIndexButton"],
    };

    let cList_button = $c.gcm.createCList(properties_button);    

    // 조건 설정 (selectbox)
    let properties_selectbox = {
        tabIndex: scwin.gVar["cTabIndexSelectBox"],
    };

    let cList_selectbox = $c.gcm.createCList(properties_selectbox);    

    let grp_comp = $c.gcm.getTestGroup();

    let strNameSpace = $c.gcm.getNameSpace();    
    let strStartComp = '';

    strStartComp += '<xf:input ' + strNameSpace + ' tabIndex="1" initValue="start" style="width:144px; height:21px;"></xf:input>';

    scwin.startcomp = await $p.dynamicCreate(
        "startcomp",
        "input",
        strStartComp,
        grp_comp
    );

    $c.gcm.createBasicAutoComplete(cList, 'ev:onfocus="scwin.target1_onfocus"')
    $c.gcm.createBasicInput(cList_input, 'ev:onfocus="scwin.input2_onfocus"', "input2");
    $c.gcm.createBasicButton(cList_button, 'ev:onfocus="scwin.button2_onfocus"', "button2");
    $c.gcm.createBasicAutoComplete(cList_selectbox, 'ev:onfocus="scwin.selectbox2_onfocus"', "selectbox2");

    // target1.setValue("target");
    input2.setValue("input");
}
